from pathlib import Path

path=Path('cloudflare/src/finance-core.js')
s=path.read_text()

def replace_once(old,new,label):
    global s
    count=s.count(old)
    if count!=1:
        raise SystemExit(f'{label}: expected exactly one anchor, found {count}')
    s=s.replace(old,new,1)

